  await test("hundreds of dynamic managers/records render with pagination, filtering and no hardcoded roster", () => { reset(); const a = A.blank(); a.managers = Array.from({ length: 250 }, (_, i) => ({ id: "scale-" + i, name: "Manager " + String(i).padStart(3, "0"), code: "S-" + i, defaultShift: i % 2 ? "night" : "day", active: true })); a.records = a.managers.flatMap((m) => [12, 13, 14].map((day) => ({ ...timed(), id: m.id + "-" + day, managerId: m.id, date: "2026-11-" + day, mode: "tap", status: "present", shift: m.defaultShift, checkIn: "", checkOut: "", breakMinutes: 0 }))); A.validate(a); S.data.attendance = a; assert.equal(S.save(true), true); H.go("attendance"); assert.equal(w.document.querySelectorAll(".att-person").length, 24); assert.ok($(".att-pager").textContent.includes("250")); A.ui().q = "Manager 249"; H.render(); assert.equal(w.document.querySelectorAll(".att-person").length, 1); A.ui().q = ""; A.ui().tab = "calendar"; H.render(); assert.ok($('.att-cal-cell[data-date="2026-11-14"]').textContent.includes("P 250")); salaryUnchanged(); });
